156	/**
157	 * A module path as an `import` in generated source can carry it.
158	 *
159	 * A test that writes a temporary `.ts` file importing something from this repository
160	 * has to put an absolute path inside a string literal, and on Windows that path is
161	 * full of backslashes — which the TypeScript it is written into reads as escapes.
162	 * `C:\repos\Atoma\atomaton\src\lib\sibling-check.ts` arrives at the loader as
163	 * `C:\reposAtomaatomatonsrclibsibling-check.ts`, and the shim fails to resolve a
164	 * package nobody named.
165	 *
166	 * A `file://` URL rather than escaped backslashes: it is what a loader takes on every
167	 * platform, and it cannot be half-applied the way manual escaping can.
168	 */
169	export function importable(absolutePath: string): string {
170	  return pathToFileURL(absolutePath).href;
