173	/**
174	 * Remove a temporary directory a test made, without failing the test over it.
175	 *
176	 * `rmSync(..., { force: true })` is not enough on Windows, where a directory a git
177	 * process touched stays locked for a moment after that process exits: the removal
178	 * throws `EBUSY`, from a `finally` block, after every assertion in the test has
179	 * already passed. `maxRetries` is exactly what Node added for that.
180	 *
181	 * And it still swallows what survives the retries. This is a temp directory the
182	 * operating system will clean up anyway; a test that cannot delete one has not found
183	 * anything about the code it was testing, and saying it failed would be false.
184	 */
185	export function removeTemp(dir: string): void {
186	  try {
187	    rmSync(dir, { recursive: true, force: true, maxRetries: 10, retryDelay: 50 });
188	  } catch {
189	    // The OS owns it now.
190	  }
191	}
